adan", "fluide_frigorigene": "R32", "topologie": "Hydrosplit (liaison hydraulique)", "alimentation_electrique": "Monophasé", "temperature_depart_max_c": 70, "unite_exterieure": "PUZ-SHWM80VAA", "module_interieur": "ERSF-VM2E", "reference_fabricant": "PUZ-SHWM80VAA + ERSF-VM2E", "type_element": "pack", "aides_estimatives_a_verifier": true, "note_reglementaire": "Valeurs techniques reprises de la liste fournie. Classe du régulateur à renseigner d'après la fiche produit (UE) 811/2013 avant validation BAR-TH-171.", "scop": 3.42, "scop_source": 3.42, "classe_energetique_35c_55c": "A+++ / A++", "gamme_source": "Haut de gamme"}}, {"nom": "Pack PAC air/eau Mitsubishi Electric Ecodan Zubadan 8 kW chauffage seul, triphasé — unité extérieure PUZ-SHWM80YAA + module hydraulique mural ERSF-VM2E, R32, 70 °C, ηs 188 % (35 °C) / 134 % (55 °C), A+++ / A++", "marque": "Mitsubishi Electric", "reference": "MITSU-PUZ-SHWM80YAA-ERSF-VM2E", "aliases": [], "pack": true, "prix_unitaire_ht": 5395.0, "description": "Pack pompe à chaleur air/eau Mitsubishi Electric Ecodan Zubadan 8 kW, triphasé, chauffage seul. Unité extérieure PUZ-SHWM80YAA + module intérieur ERSF-VM2E. Fluide frigorigène : R32. Topologie : hydrosplit (liaison hydraulique). Température de départ maximale : 70 °C. ETAS : 134 % à 55 °C et 188 % à 35 °C. SCOP : 3,42. Classes énergétiques : A+++ à 35 °C / A++ à 55 °C.", "caracteristiques": {"fiche_cee": "BAR-TH-171", "usage": "Chauffage seul", "temp": "Moyenne ou haute température", "etas": 134, "etas_55c_pct": 134.0, "etas_35c_pct": 188.0, "puissance_nominale_indiquee_kw": 8.0, "gamme": "Ecodan Zubadan", "fluide_frigorigene": "R32", "topologie": "Hydrosplit (liaison hydraulique)", "alimentation_electrique": "Triphasé", "temperature_depart_max_c": 70, "unite_exterieure": "PUZ-SHWM80YAA", "module_interieur": "ERSF-VM2E", "reference_fabricant": "PUZ-SHWM80YAA + ERSF-VM2E", "type_element": "pack", "aides_estimatives_a_verifier": true, "note_reglementaire": "Valeurs techniques reprises de la liste fournie. Classe du régulateur à renseigner d'après la fiche produit (UE) 811/2013 avant validation BAR-TH-171.", "scop": 3.42, "scop_source": 3.42, "classe_energetique_35c_55c": "A+++ / A++", "gamme_source": "Haut de gamme"}}, {"nom": "Module Duo avec ballon ECS intégré Mitsubishi Electric Ecodan ERST20F-VM2E-M — variante « E-Gen », appoint électrique 2 kW, ballon ECS 200 L intégré (vendu seul)", "marque": "Mitsubishi Electric", "reference": "MITSU-ERST20F-VM2E-M", "aliases": [], "pack": false, "prix_unitaire_ht": 3540.0, "description": "Module Duo avec ballon ECS intégré Mitsubishi Electric Ecodan ERST20F-VM2E-M, variante « E-Gen », appoint électrique 2 kW, ballon ECS 200 L intégré (vendu seul).", "caracteristiques": {"type_element": "composant", "composant_vendu_seul": true, "module_interieur": "ERST20F-VM2E-M", "reference_fabricant": "ERST20F-VM2E-M", "volume_ballon_ecs_l": 200}}, {"nom": "Module hydraulique mural Mitsubishi Electric Ecodan ERSF-VM2E — variante « E-Gen », appoint électrique 2 kW (vendu seul)", "marque": "Mitsubishi Electric", "reference": "MITSU-ERSF-VM2E", "aliases": [], "pack": false, "prix_unitaire_ht": 2160.0, "description": "Module hydraulique mural Mitsubishi Electric Ecodan ERSF-VM2E, variante « E-Gen », appoint électrique 2 kW (vendu seul).", "caracteristiques": {"type_element": "composant", "composant_vendu_seul": true, "module_interieur": "ERSF-VM2E", "reference_fabricant": "ERSF-VM2E"}}]$produits$::jsonb) LOOP
    v_pack := (p->>'pack')::boolean;
    v_aliases := ARRAY(SELECT jsonb_array_elements_text(p->'aliases'));

    SELECT id INTO v_id
    FROM catalogue_produits
    WHERE categorie = 'pac_air_eau'
      AND (reference = p->>'reference' OR reference = ANY(v_aliases))
    ORDER BY (reference = p->>'reference') DESC, actif DESC, created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, unite, tva_taux, eligible_mpr, eligible_cee, fiche_cee, actif,
        public_cible, catalogue_groupe, forfait_pose_ht, forfait_evacuation_ht
      ) VALUES (
        v_entreprise, 'pac_air_eau', p->>'nom', p->>'marque', p->>'reference', p->>'description',
        p->'caracteristiques',
        COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, 0),
        'unite',
        CASE WHEN v_pack THEN 5.5 ELSE 20 END,
        v_pack, v_pack,
        CASE WHEN v_pack THEN 'BAR-TH-171' ELSE '' END,
        true, 'particulier', 'particulier', 0, 0
      );
      v_ajoutes := v_ajoutes + 1;
    ELSE
      UPDATE catalogue_produits SET
        nom = p->>'nom',
        marque = p->>'marque',
        reference = p->>'reference',
        description = CASE
          WHEN COALESCE(btrim(description), '') = ''
            OR description = nom
            OR description = p->>'nom'
            OR description LIKE 'Pack PAC air/eau %'
            OR description LIKE 'Module intérieur PAC air/eau %'
            OR description LIKE 'Unité extérieure PAC air/eau %'
            OR description LIKE 'Kit Daikin %'
            OR description LIKE 'Module Duo %'
            OR description LIKE 'Module hydraulique mural %'
          THEN p->>'description'
          ELSE description
        END,
        caracteristiques = (COALESCE(caracteristiques, '{}'::jsonb)
                              - 'pose_non_fournie_dans_source'::text
                              - 'aides_a_verifier_sur_fiche_officielle'::text
                              - 'prix_a_renseigner'::text
                              - CASE WHEN v_pack THEN '' ELSE 'fiche_cee' END)
                           || ((p->'caracteristiques') - 'prix_a_renseigner'::text)
                           || CASE WHEN array_length(v_aliases, 1) > 0
                                THEN jsonb_build_object('ancienne_reference', v_aliases[1])
                                ELSE '{}'::jsonb END,
        prix_unitaire_ht = COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, prix_unitaire_ht),
        tva_taux = CASE WHEN v_pack THEN 5.5 ELSE tva_taux END,
        fiche_cee = CASE WHEN v_pack THEN 'BAR-TH-171' ELSE '' END,
        eligible_cee = v_pack,
        eligible_mpr = v_pack,
        actif = true,
        public_cible = 'particulier',
        catalogue_groupe = 'particulier'
      WHERE id = v_id;
      v_maj := v_maj + 1;
    END IF;
    v_id := NULL;
  END LOOP;

  -- Drapeau « prix à renseigner » : uniquement pour les produits de la liste toujours sans prix.
  UPDATE catalogue_produits
  SET caracteristiques = CASE
