aleurs techniques reprises de la liste fournie. Classe du régulateur à renseigner d'après la fiche produit (UE) 811/2013 avant validation BAR-TH-171.", "scop": 3.42, "scop_source": 3.42, "classe_energetique_35c_55c": "A+++ / A++", "gamme_source": "Haut de gamme"}}, {"nom": "Module Duo avec ballon ECS intégré Mitsubishi Electric Ecodan ERST20F-VM2E-M — variante « E-Gen », appoint électrique 2 kW, ballon ECS 200 L intégré (vendu seul)", "marque": "Mitsubishi Electric", "reference": "MITSU-ERST20F-VM2E-M", "aliases": [], "pack": false, "prix_unitaire_ht": 3540.0, "description": "Module Duo avec ballon ECS intégré Mitsubishi Electric Ecodan ERST20F-VM2E-M, variante « E-Gen », appoint électrique 2 kW, ballon ECS 200 L intégré (vendu seul).", "caracteristiques": {"type_element": "composant", "composant_vendu_seul": true, "module_interieur": "ERST20F-VM2E-M", "reference_fabricant": "ERST20F-VM2E-M", "volume_ballon_ecs_l": 200}}, {"nom": "Module hydraulique mural Mitsubishi Electric Ecodan ERSF-VM2E — variante « E-Gen », appoint électrique 2 kW (vendu seul)", "marque": "Mitsubishi Electric", "reference": "MITSU-ERSF-VM2E", "aliases": [], "pack": false, "prix_unitaire_ht": 2160.0, "description": "Module hydraulique mural Mitsubishi Electric Ecodan ERSF-VM2E, variante « E-Gen », appoint électrique 2 kW (vendu seul).", "caracteristiques": {"type_element": "composant", "composant_vendu_seul": true, "module_interieur": "ERSF-VM2E", "reference_fabricant": "ERSF-VM2E"}}]$produits$::jsonb));

  -- Fusion des doublons issus du fichier Excel du 20/10/2026.
  FOR d IN SELECT value FROM jsonb_array_elements($doublons$[{"marque": "Daikin", "reference": "ERGA06EVH + EHVH08S18E6V", "canon": "DAIKIN-ERGA06EVH-EHVH08S18E6V"}, {"marque": "Daikin", "reference": "ERGA08EVH7 + EHVH08S18E6V", "canon": "DAIKIN-ERGA08EVH7-EHVH08S18E6V"}, {"marque": "Daikin", "reference": "ERLA11DV3 + EBVH11S18D6V", "canon": "DAIKIN-ERLA11DV3-EBVH11S18D6V"}, {"marque": "Daikin", "reference": "ERLA14DV3 + EBVH16S18D6V", "canon": "DAIKIN-ERLA14DV3-EBVH16S18D6V"}, {"marque": "Daikin", "reference": "ERLA16DV37 + EBVH16S18D6V", "canon": "DAIKIN-ERLA16DV37-EBVH16S18D6V"}, {"marque": "Mitsubishi", "reference": "PUZ-SHWM100VAA", "canon": "MITSU-PUZ-SHWM100VAA-ERST20F-VM2E-M"}]$doublons$::jsonb) LOOP
    SELECT id INTO v_canon FROM catalogue_produits
    WHERE categorie = 'pac_air_eau' AND reference = d->>'canon'
    ORDER BY actif DESC, created_at NULLS LAST LIMIT 1;
    CONTINUE WHEN v_canon IS NULL;

    FOR v_dup IN
      SELECT id, forfait_pose_ht, forfait_evacuation_ht, caracteristiques
      FROM catalogue_produits
      WHERE categorie = 'pac_air_eau' AND id <> v_canon
        AND marque = d->>'marque' AND reference = d->>'reference'
    LOOP
      UPDATE catalogue_produits SET
        forfait_pose_ht = CASE WHEN COALESCE(forfait_pose_ht, 0) > 0 THEN forfait_pose_ht ELSE COALESCE(v_dup.forfait_pose_ht, 0) END,
        forfait_evacuation_ht = CASE WHEN COALESCE(forfait_evacuation_ht, 0) > 0 THEN forfait_evacuation_ht ELSE COALESCE(v_dup.forfait_evacuation_ht, 0) END,
        caracteristiques = (COALESCE(v_dup.caracteristiques, '{}'::jsonb)
                              - 'fiche_cee'::text - 'source_tarifs'::text - 'source_date'::text
                              - 'prix_fourniture_ht'::text - 'forfait_pose_ht'::text - 'doublon_de'::text - 'ancienne_reference'::text)
                           || COALESCE(caracteristiques, '{}'::jsonb)
      WHERE id = v_canon;

      UPDATE catalogue_produits SET
        actif = false,
        caracteristiques = COALESCE(caracteristiques, '{}'::jsonb) || jsonb_build_object('doublon_de', d->>'canon')
      WHERE id = v_dup.id;
      v_doublons := v_doublons + 1;
    END LOOP;
    v_canon := NULL;
  END LOOP;

  RAISE NOTICE 'Daikin / Mitsubishi : % ajouté(s), % mis à jour, % doublon(s) Excel fusionné(s)', v_ajoutes, v_maj, v_doublons;
END $$;
